export { ListMenu } from './list-menu';
export { ListMenuTrigger } from './list-menu-trigger';
export { ListMenuPopover } from '@salesforce/retail-react-app/app/components/list-menu/list-menu-popover';
export { ListMenuContent } from '@salesforce/retail-react-app/app/components/list-menu/list-menu-content';

import type { ImageEntry } from 'app/types/contentful';

export type ResolvedImage = {
  src: string;
  alt: string;
};

/**
 * Resolves a Contentful `image` entry (the reusable asset + accessible-metadata primitive —
 * see ImageEntry's own doc comment) down to the `{src, alt}` shape every `<Image>` render site
 * actually needs. Shared by megaMenuContent/toMegaMenuItem.ts (desktop/tablet) and
 * drawer-menu/index.tsx (mobile L2) — both resolve the same field shape.
 *
 * `decorative` short-circuits to an empty alt (screen readers skip it) regardless of whether
 * `altText` also happens to be set — an editor marking an image decorative is asserting no
 * fallback is warranted, not just skipping the field. Absent decorative/altText, falls back to
 * the underlying asset's own description/title, matching this field's pre-migration behaviour
 * when it linked a raw Asset directly.
 *
 * @param image the `promoImage`-shaped field value, or undefined if unset
 * @returns the resolved `{src, alt}`, or undefined if no image/asset is actually linked
 */
export const resolveImageEntry = (image: ImageEntry | undefined): ResolvedImage | undefined => {
  const asset = image?.fields.asset;
  if (!asset) return undefined;

  const alt = image.fields.decorative ? '' : image.fields.altText ?? asset.fields.description ?? asset.fields.title;

  return { src: asset.fields.file.url, alt };
};

/**
 * Builds Contentful Images API AVIF/WebP `srcSet` pairs for a target display size, with a real
 * @2x variant (not just a bigger single image) — used for the header mega-menu's promo images
 * (desktop/tablet: megaMenuContent/index.tsx, mobile drawer L2: drawer-menu/index.tsx).
 *
 * Deliberately not PWA Kit's `getResponsivePictureAttributes`/`DynamicImage`
 * (@salesforce/retail-react-app/app/utils/responsive-image.js): that utility substitutes one
 * literal value into every `{...}` placeholder in a URL template, so a real @2x (both width AND
 * height doubled) needs its own explicit URL anyway — building both directly is simpler and
 * more correct.
 *
 * `fit=fill` (cover-crop to exactly fill the target box) with NO `f` (focus) param — this is a
 * deliberate reversal of two earlier versions of this file:
 *   1. `fit=fill&f=face` (Contentful's face-detection focal point) — real production assets
 *      showed this cropping out the model's head/face entirely regardless of focal-point
 *      accuracy (confirmed against Clothing/Accessories/Collections, even the "easy" clear
 *      front-facing case). `f=face` is unreliable here, not just imprecise.
 *   2. Width-only (no `h`/`fit` at all, so nothing crops) — fixed the face-crop bug, but broke
 *      the box-fill requirement: the mobile L2 box (drawer-menu.css.ts's `flex: 1`) must fill
 *      edge-to-edge per Figma, and a landscape source scaled to fit a portrait box always
 *      leaves visible empty space no matter how the box itself is sized.
 * Testing confirmed Contentful's *default* crop (no `f` at all) reliably keeps the full subject
 * in frame across every real asset and every realistic box height: these source photos are all
 * landscape (~1728x1380), so cropping into a narrower/taller target only ever trims the left/
 * right edges, never the top/bottom where a head or feet would be cut off — the earlier bug was
 * `f=face` overriding that safe default, not `fit=fill` cropping itself.
 *
 * AVIF first, WebP fallback: q=65 AVIF and q=95 WebP were both visually clean (no compression
 * grain) against real production assets, comfortably under the 300-400KB the client confirmed
 * is an acceptable ceiling for lazy-loaded, non-LCP imagery. See project memory for the full
 * before/after comparison.
 */

export type ContentfulImageTarget = {
  width: number;
  height: number;
};

export type ContentfulResponsiveImage = {
  /** AVIF 1x/2x srcSet for a <source type="image/avif">. Empty string for a `data:` URI
   *  fixture (Storybook/tests) — there's no real AVIF variant to build for one, and an empty
   *  string is falsy so call sites can skip rendering that <source> entirely. */
  avifSrcSet: string;
  /** WebP 1x src — the <img> fallback for browsers with no AVIF support. */
  webpSrc: string;
  /** WebP 1x/2x srcSet, for the same <img> fallback. */
  webpSrcSet: string;
};

const AVIF_QUALITY = 65;
const WEBP_QUALITY = 95;

const buildUrl = (url: string, width: number, height: number, format: 'avif' | 'webp', quality: number): string =>
  `${url}?w=${width}&h=${height}&fit=fill&fm=${format}&q=${quality}`;

/**
 * @param url Contentful asset URL (protocol-relative, e.g. `//images.ctfassets.net/...`) —
 * from `asset.fields.file.url`, with no existing query params.
 * @param target Display size (CSS pixels) to crop-to-fill at 1x.
 */
export const buildContentfulResponsiveImage = (
  url: string,
  target: ContentfulImageTarget,
): ContentfulResponsiveImage => {
  // A data: URI can't take appended query params (everything after the comma is the payload,
  // not a path) — the real app never sees one here (Contentful asset URLs are always real CDN
  // paths), but Storybook fixtures deliberately use inline SVG data URIs to stay CI-safe (no
  // external network fetch) — see megaMenuContent/index.stories.tsx's own promoSvg() comment.
  // Passing it through unmodified rather than corrupting it, and skipping the (meaningless) AVIF
  // variant entirely.
  if (url.startsWith('data:')) {
    return { avifSrcSet: '', webpSrc: url, webpSrcSet: `${url} 1x` };
  }

  const avif1x = buildUrl(url, target.width, target.height, 'avif', AVIF_QUALITY);
  const avif2x = buildUrl(url, target.width * 2, target.height * 2, 'avif', AVIF_QUALITY);
  const webp1x = buildUrl(url, target.width, target.height, 'webp', WEBP_QUALITY);
  const webp2x = buildUrl(url, target.width * 2, target.height * 2, 'webp', WEBP_QUALITY);

  return {
    avifSrcSet: `${avif1x} 1x, ${avif2x} 2x`,
    webpSrc: webp1x,
    webpSrcSet: `${webp1x} 1x, ${webp2x} 2x`,
  };
};

import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { Image } from '@salesforce/retail-react-app/app/components/shared/ui';
import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem';
import type { HeaderNavItemEntry } from 'app/types/contentful';
import { toMegaMenuItem } from './toMegaMenuItem';
import { MEGA_MENU_HEADING_LINK_CLASS } from './megaMenuContent.css';
import type { MegaMenuSection } from './types';

const MEGA_MENU_CONTENT_RECIPE = 'ZimmMegaMenuContent';

// Every leaf link the panel can contain (SectionColumn's ZimmNavItems) — see handlePanelKeyDown.
const PANEL_FOCUSABLE_SELECTOR = 'a[href], button:not([disabled])';

/**
 * Up/Down arrow navigation across every leaf link in the open panel, flattened across columns
 * in DOM order and wrapping at either end — the simplest mental model for a multi-column mega
 * menu, per the confirmed design decision for this component (as opposed to a per-column
 * grid with Left/Right switching columns). Escape is not handled here — Chakra's Popover
 * already closes on Escape from anywhere within its content (`closeOnEsc`, on by default).
 */
const handlePanelKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
  if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return;

  const focusables = Array.from(e.currentTarget.querySelectorAll<HTMLElement>(PANEL_FOCUSABLE_SELECTOR));
  if (focusables.length === 0) return;
  e.preventDefault();

  const currentIndex = focusables.indexOf(document.activeElement as HTMLElement);
  let nextIndex: number;
  if (currentIndex === -1) {
    nextIndex = e.key === 'ArrowDown' ? 0 : focusables.length - 1;
  } else {
    const delta = e.key === 'ArrowDown' ? 1 : -1;
    nextIndex = (currentIndex + delta + focusables.length) % focusables.length;
  }
  focusables[nextIndex]?.focus();
};

// Leaf-link typography: Default/Navigation (12px) at tablet/desktop, h3-strong (16px) mobile.
const LEAF_LINK_SX = {
  textStyle: { base: 'heading3', md: 'navigation' },
};

// A two-column item's first link (e.g. "Ready to Wear" under Collections) is styled like a
// heading while staying a real clickable ZimmNavItem, per Figma — not a separate `heading`
// field, the design intentionally makes this item both. marginBottom reproduces
// sectionHeading's 16px gap-to-list-below. This item also gets MEGA_MENU_HEADING_LINK_CLASS
// below so sectionLinks' CSS can cancel its own row gap immediately after it — see that
// selector's comment in megaMenuContent.css.ts.
const PRIMARY_LEAF_LINK_SX = {
  textStyle: { base: 'heading1Strong', md: 'navigation' },
  marginBottom: 'var(--zimm-scale-m)',
};

type MegaMenuContentProps = {
  item: HeaderNavItemEntry;
  itemsKey: string;
  /** ZimmNavItem doesn't forward refs, so this lands on the panel container instead of the
   *  first leaf link (tabIndex={-1}, programmatically focusable only). */
  initialFocusRef?: React.Ref<HTMLDivElement>;
  onClose?: () => void;
  maxColumns?: number;
  /** Real popover open state, added by list-menu-popover.tsx's override — currently unused
   *  here (the header-shell open/close report lives in ListMenuView instead, see list-menu.tsx)
   *  but kept in the contract since ListMenuPopover passes it through generically. */
  isOpen?: boolean;
  /**
   * Whether the panel's reveal/fade animation has genuinely finished, not merely started —
   * distinct from `isOpen` above (true for the whole animation, not just its end). Defaults to
   * `true` so a story/test rendering this component standalone (no ListMenuPopover driving a
   * real motion phase) keeps normal tab behaviour.
   *
   * Gates every leaf link's `tabIndex` to `-1` while `false` — confirmed live against a real
   * browser (Storybook test-runner): Chakra's Popover flips `visibility: visible` on its
   * positioner the instant it opens, well before this panel's own CSS reveal (0-height,
   * `overflow: hidden`, `opacity: 0`) finishes — and a 0-height/overflow-hidden ancestor does
   * NOT reliably remove a real `<a>`/`<button>` descendant from the Tab order on its own, only
   * from view. Without this, Tab pressed quickly after opening could land focus on a link that
   * was still invisible (WCAG 2.4.7). `visibility: hidden` on the content itself was considered
   * and rejected — it would also suppress the fade transition it's meant to be gating, not just
   * remove tabbability.
   */
  isFullyOpen?: boolean;
};

type SectionColumnProps = {
  section: MegaMenuSection;
  styles: Record<string, Record<string, unknown>>;
  onClose?: () => void;
  /** Two-column mega menus (e.g. Collections) style each section's first link as a heading —
   *  see PRIMARY_LEAF_LINK_SX above. */
  isTwoColumn?: boolean;
  /** See MegaMenuContentProps' own doc comment. */
  isFullyOpen: boolean;
};

const SectionColumn = ({ section, styles, onClose, isTwoColumn, isFullyOpen }: SectionColumnProps) => (
  <chakra.div __css={styles.section}>
    {section.heading && <chakra.p __css={styles.sectionHeading}>{section.heading}</chakra.p>}
    <chakra.div __css={styles.sectionLinks}>
      {section.links.map((link, index) => (
        <ZimmNavItem
          key={link.href}
          label={link.label}
          href={link.href}
          onClick={onClose}
          sx={isTwoColumn && index === 0 ? PRIMARY_LEAF_LINK_SX : LEAF_LINK_SX}
          className={isTwoColumn && index === 0 ? MEGA_MENU_HEADING_LINK_CLASS : undefined}
          growUnderline
          tabIndex={isFullyOpen ? undefined : -1}
        />
      ))}
    </chakra.div>
  </chakra.div>
);

/** Rich mega-menu popover content — renders a headerNavItem's columns plus an optional promo
 *  image. All Contentful-shape knowledge is isolated in `toMegaMenuItem`. */
export const MegaMenuContent = ({
  item,
  itemsKey,
  initialFocusRef,
  onClose,
  isFullyOpen = true,
}: MegaMenuContentProps) => {
  const styles = useMultiStyleConfig(MEGA_MENU_CONTENT_RECIPE);
  const { columns, promoImage } = toMegaMenuItem(item, itemsKey);
  // Only twoColumnLayout ever produces more than one column — see toMegaMenuItem.ts.
  const isTwoColumn = columns.length > 1;

  return (
    <chakra.div ref={initialFocusRef} tabIndex={-1} __css={styles.panel} onKeyDown={handlePanelKeyDown}>
      <chakra.div __css={styles.sections}>
        {columns.map((column, columnIndex) => (
          <chakra.div key={`column-${columnIndex}`} __css={styles.column}>
            {column.map((section, index) => (
              <SectionColumn
                key={`section-${index}`}
                section={section}
                styles={styles}
                onClose={onClose}
                isTwoColumn={isTwoColumn}
                isFullyOpen={isFullyOpen}
              />
            ))}
          </chakra.div>
        ))}
      </chakra.div>
      {promoImage && (
        <chakra.div __css={styles.promoImageWrapper}>
          <Image src={promoImage.src} alt={promoImage.alt} loading="lazy" __css={styles.promoImage} />
        </chakra.div>
      )}
    </chakra.div>
  );
};

MegaMenuContent.displayName = 'MegaMenuContent';
